export class ControlPlaneStore {
  readonly db:DatabaseSync;
  constructor(path:string){if(path!==':memory:')mkdirSync(dirname(path),{recursive:true});this.db=new DatabaseSync(path,{timeout:1000});this.db.exec('PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;');this.db.exec(`
    CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,title TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS product_versions(id TEXT NOT NULL,version TEXT NOT NULL,definition TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(id,version),FOREIGN KEY(id) REFERENCES products(id));
    CREATE TABLE IF NOT EXISTS builds(id TEXT PRIMARY KEY,product_id TEXT NOT NULL,version TEXT NOT NULL,state TEXT NOT NULL,artifact_digest TEXT,created INTEGER NOT NULL,updated INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS environments(id TEXT PRIMARY KEY,label TEXT NOT NULL,kind TEXT NOT NULL,target TEXT NOT NULL,region TEXT,created INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS deployments(id TEXT PRIMARY KEY,environment_id TEXT NOT NULL,product_id TEXT NOT NULL,version TEXT NOT NULL,build_id TEXT,state TEXT NOT NULL,created INTEGER NOT NULL,updated INTEGER NOT NULL);
    CREATE TABLE IF NOT EXISTS ai_pipelines(id TEXT NOT NULL,version TEXT NOT NULL,spec TEXT NOT NULL,digest TEXT NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(id,version));
    CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,subject TEXT NOT NULL,payload TEXT NOT NULL,at INTEGER NOT NULL);
  `);}
  private audit(action:string,subject:string,payload:unknown){this.db.prepare('INSERT INTO audit(action,subject,payload,at) VALUES(?,?,?,?)').run(action,subject,canonical(payload),Date.now());}
  putProduct(definition:ProductDefinition){const now=Date.now();this.db.prepare('INSERT INTO products(id,title,created,updated) VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET title=excluded.title,updated=excluded.updated').run(definition.id,definition.title,now,now);this.db.prepare('INSERT OR REPLACE INTO product_versions(id,version,definition,created) VALUES(?,?,?,?)').run(definition.id,definition.version,canonical(definition),now);this.audit('product.version.put',`${definition.id}@${definition.version}`,definition);return definition;}
  products(){return this.db.prepare(`SELECT p.id,p.title,p.updated,(SELECT version FROM product_versions v WHERE v.id=p.id ORDER BY created DESC LIMIT 1) AS version FROM products p ORDER BY p.id`).all();}
  product(id:string,version?:string):ProductDefinition|undefined{const row=version?this.db.prepare('SELECT definition FROM product_versions WHERE id=? AND version=?').get(id,version):this.db.prepare('SELECT definition FROM product_versions WHERE id=? ORDER BY created DESC LIMIT 1').get(id) as {definition:string}|undefined;return row?JSON.parse(String((row as {definition:string}).definition)):undefined;}
  requestBuild(productId:string,version:string){if(!this.product(productId,version))throw new PlatformError('NOT_FOUND','Product version not found');const id=randomUUID(),now=Date.now();this.db.prepare('INSERT INTO builds VALUES(?,?,?,?,?,?,?)').run(id,productId,version,'QUEUED',null,now,now);this.audit('build.request',id,{productId,version});return {id,productId,version,state:'QUEUED' as BuildState};}
  builds(){return this.db.prepare('SELECT id,product_id AS productId,version,state,artifact_digest AS artifactDigest,created,updated FROM builds ORDER BY created DESC').all();}
  putEnvironment(spec:EnvironmentSpec){if(!/^[a-z][a-z0-9-]{1,47}$/.test(spec.id))throw new PlatformError('INVALID','Invalid environment id');this.db.prepare('INSERT OR REPLACE INTO environments VALUES(?,?,?,?,?,?)').run(spec.id,spec.label,spec.kind,spec.target,spec.region??null,Date.now());this.audit('environment.put',spec.id,spec);return spec;}
  environments(){return this.db.prepare('SELECT id,label,kind,target,region,created FROM environments ORDER BY kind,id').all();}
  requestDeployment(environmentId:string,productId:string,version:string,buildId?:string){if(!this.db.prepare('SELECT 1 FROM environments WHERE id=?').get(environmentId))throw new PlatformError('NOT_FOUND','Environment not found');if(!this.product(productId,version))throw new PlatformError('NOT_FOUND','Product version not found');const id=randomUUID(),now=Date.now();this.db.prepare('INSERT INTO deployments VALUES(?,?,?,?,?,?,?,?)').run(id,environmentId,productId,version,buildId??null,'REQUESTED',now,now);this.audit('deployment.request',id,{environmentId,productId,version,buildId});return {id,environmentId,productId,version,buildId:buildId??null,state:'REQUESTED' as DeploymentState};}
  deployments(){return this.db.prepare('SELECT id,environment_id AS environmentId,product_id AS productId,version,build_id AS buildId,state,created,updated FROM deployments ORDER BY created DESC').all();}
  putAiPipeline(pipeline:AiPipeline){const plan=planAiPipeline(pipeline);this.db.prepare('INSERT OR REPLACE INTO ai_pipelines VALUES(?,?,?,?,?)').run(pipeline.id,pipeline.version,canonical(pipeline),plan.digest,Date.now());this.audit('ai.pipeline.put',`${pipeline.id}@${pipeline.version}`,{digest:plan.digest});return plan;}
  aiPipelines(){return (this.db.prepare('SELECT id,version,spec,digest,created FROM ai_pipelines ORDER BY id,created DESC').all() as unknown as {id:string;version:string;spec:string;digest:string;created:number}[]).map(r=>({...r,spec:JSON.parse(r.spec)}));}
  auditLog(limit=100){return this.db.prepare('SELECT id,action,subject,payload,at FROM audit ORDER BY id DESC LIMIT ?').all(limit);}
  close(){this.db.close();}
}
import { PlatformError, type CompositionPlan, type ModuleManifest } from '@quadbridge/contracts';

export type StudioLayer = 'ui' | 'backend' | 'ai' | 'data' | 'worker' | 'integration' | 'deployment';
export interface UiContribution {
  routes?: { path: string; workspace: string; label: string; nav?: string; extensionPoint?: string }[];
  extensionPoints?: string[];
}
export interface BackendContribution {
  services?: { id: string; contract: string; visibility: 'module' | 'product' }[];
  events?: { id: string; direction: 'publish' | 'subscribe'; schema: string }[];
  jobs?: { kind: string; permission: string }[];
}
export interface AiModelRequirement {
  capability: string;
  modality: 'text' | 'vision' | 'audio' | 'embedding' | 'rerank' | 'custom';
  placement: 'cloud' | 'edge' | 'either';
  minContext?: number;
  accelerator?: 'cpu' | 'gpu' | 'npu' | 'either';
}
export interface AiContribution {
  pipelines?: { id: string; label: string; input: string; output: string }[];
  models?: AiModelRequirement[];
  tools?: { id: string; contract: string; permission: string }[];
}
export interface DataContribution {
  stores?: { id: string; kind: 'relational' | 'object' | 'vector' | 'graph' | 'cache' | 'timeseries'; ownership: 'module' | 'product' }[];
  schemas?: { id: string; version: number }[];
}
export interface DeploymentContribution {
  processes?: { id: string; kind: 'http' | 'worker' | 'model-server' | 'scheduler'; replicas?: number }[];
  resources?: { process: string; cpu?: string; memory?: string; gpu?: string; npu?: string }[];
  secrets?: string[];
  ports?: number[];
}
export interface ModuleStudioMetadata {
  label?: string;
  summary?: string;
  category?: string;
  layers?: StudioLayer[];
  ui?: UiContribution;
  backend?: BackendContribution;
  ai?: AiContribution;
  data?: DataContribution;
  deployment?: DeploymentContribution;
}
export type StudioModuleManifest = ModuleManifest & { studio?: ModuleStudioMetadata };

const safeId = /^[a-z][a-z0-9.-]{1,95}$/;
export function validateStudioModule(manifest: StudioModuleManifest): StudioModuleManifest {
  if (!safeId.test(manifest.id)) throw new PlatformError('INVALID', 'Invalid module id');
  const metadata = manifest.studio;
  if (!metadata) return manifest;
  for (const layer of metadata.layers ?? []) {
    if (!['ui','backend','ai','data','worker','integration','deployment'].includes(layer)) throw new PlatformError('INVALID', `Unknown Studio layer ${layer}`);
  }
  for (const pipeline of metadata.ai?.pipelines ?? []) if (!safeId.test(pipeline.id)) throw new PlatformError('INVALID', 'Invalid AI pipeline id');
  for (const store of metadata.data?.stores ?? []) if (!safeId.test(store.id)) throw new PlatformError('INVALID', 'Invalid data store id');
  for (const process of metadata.deployment?.processes ?? []) if (!safeId.test(process.id)) throw new PlatformError('INVALID', 'Invalid deployment process id');
  return manifest;
}

export interface LayerCoverage { layer: StudioLayer; modules: string[]; implemented: boolean; detail: string }
export function summarizePlan(plan: CompositionPlan): LayerCoverage[] {
  const modules = plan.modules as StudioModuleManifest[];
  const has = (layer: StudioLayer) => modules.filter(m => m.studio?.layers?.includes(layer)).map(m => m.id);
  return [
    { layer: 'ui', modules: has('ui'), implemented: modules.some(m => m.workspaces.length > 0), detail: `${modules.reduce((n,m)=>n+m.workspaces.length,0)} declared workspaces` },
    { layer: 'backend', modules: has('backend'), implemented: modules.some(m => m.routes.length > 0), detail: `${modules.reduce((n,m)=>n+m.routes.length,0)} declared HTTP operations` },
    { layer: 'worker', modules: has('worker'), implemented: plan.requiresWorker, detail: plan.requiresWorker ? 'Worker runtime required by composition' : 'No worker required' },
    { layer: 'integration', modules: has('integration'), implemented: plan.bindings.length > 0, detail: `${plan.bindings.length} resolved bindings` },
    { layer: 'ai', modules: has('ai'), implemented: has('ai').length > 0, detail: `${modules.reduce((n,m)=>n+(m.studio?.ai?.pipelines?.length ?? 0),0)} declared AI pipelines` },
    { layer: 'data', modules: has('data'), implemented: has('data').length > 0, detail: `${modules.reduce((n,m)=>n+(m.studio?.data?.stores?.length ?? 0),0)} declared data stores` },
    { layer: 'deployment', modules: has('deployment'), implemented: false, detail: 'Deployment contracts declared; production orchestrator not yet attached' }
  ];
}
